using System.Collections.Generic;using Alterverse.Profile;using UnityEngine;
namespace Alterverse.Audio
{
public enum DimensionSound{HitLight,HitHeavy,RecallStart,RecallComplete,RecallCancel,RealityShatter,FrontShift,Overtime,SuddenDeath,Victory,Defeat,UiConfirm,UiBack}
public sealed class DimensionAudio:MonoBehaviour
{
private static DimensionAudio instance;private readonly Dictionary<DimensionSound,AudioClip> clips=new();private readonly List<AudioSource> voices=new();private const int VoiceCount=8;[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]private static void AutoCreate(){if(FindAnyObjectByType<DimensionAudio>()==null)new GameObject("DF_Audio").AddComponent<DimensionAudio>();}private void Awake(){if(instance!=null&&instance!=this){Destroy(gameObject);return;}instance=this;for(int i=0;i<VoiceCount;i++){AudioSource s=gameObject.AddComponent<AudioSource>();s.playOnAwake=false;s.spatialBlend=0f;voices.Add(s);}Build();}public static void Play(DimensionSound sound,float volume=1f,float pitch=1f){if(instance==null||!instance.clips.TryGetValue(sound,out AudioClip clip))return;AudioSource voice=instance.NextVoice();voice.pitch=Mathf.Clamp(pitch,.5f,1.8f);voice.clip=clip;voice.volume=Mathf.Clamp01(volume)*PlayerProfile.MasterVolume*PlayerProfile.SfxVolume;voice.Play();}private AudioSource NextVoice(){for(int i=0;i<voices.Count;i++)if(!voices[i].isPlaying)return voices[i];AudioSource oldest=voices[0];float least=oldest.time;for(int i=1;i<voices.Count;i++)if(voices[i].time>least){oldest=voices[i];least=voices[i].time;}oldest.Stop();return oldest;}
private void Build(){Add(DimensionSound.HitLight,.075f,980,180,.38f,true);Add(DimensionSound.HitHeavy,.13f,220,70,.55f,true);Add(DimensionSound.RecallStart,.32f,180,520,.32f,false);Add(DimensionSound.RecallComplete,.28f,430,1180,.42f,false);Add(DimensionSound.RecallCancel,.14f,520,110,.30f,true);Add(DimensionSound.RealityShatter,.42f,125,1450,.48f,true);Add(DimensionSound.FrontShift,.18f,310,620,.25f,true);Add(DimensionSound.Overtime,.62f,145,480,.38f,true);Add(DimensionSound.SuddenDeath,.72f,95,760,.48f,true);Add(DimensionSound.Victory,.68f,280,980,.42f,false);Add(DimensionSound.Defeat,.62f,310,82,.40f,true);Add(DimensionSound.UiConfirm,.07f,620,940,.22f,false);Add(DimensionSound.UiBack,.06f,540,310,.18f,false);}private void Add(DimensionSound sound,float seconds,float a,float b,float gain,bool grit)=>clips[sound]=Tone("DF_"+sound,seconds,a,b,gain,grit);
private static AudioClip Tone(string name,float seconds,float startHz,float endHz,float gain,bool grit){int rate=22050,count=Mathf.Max(1,Mathf.RoundToInt(seconds*rate));float[] data=new float[count];uint noise=2463534242;for(int i=0;i<count;i++){float t=i/(float)count,hz=Mathf.Lerp(startHz,endHz,t),env=Mathf.Sin(Mathf.PI*t)*Mathf.Pow(1f-t,.35f),phase=2*Mathf.PI*hz*i/rate;float s=Mathf.Sin(phase)+.28f*Mathf.Sin(phase*2.01f);if(grit){noise^=noise<<13;noise^=noise>>17;noise^=noise<<5;s+=(((noise&65535)/32767.5f)-1f)*.18f;}data[i]=Mathf.Clamp(s*env*gain,-1,1);}AudioClip clip=AudioClip.Create(name,count,1,rate,false);clip.SetData(data,0);return clip;}private void OnDestroy(){foreach(AudioSource voice in voices)if(voice!=null)voice.Stop();foreach(AudioClip clip in clips.Values)if(clip!=null)Destroy(clip);clips.Clear();voices.Clear();if(instance==this)instance=null;}
}
}
